<?php
if(str_starts_with($route,'admin')){require dirname(__DIR__).'/app/admin.php';exit;}
if($route===''){$latest=[];$featured=[];$popular=[];$categories=[];$catName="(SELECT c.name FROM article_category x JOIN categories c ON c.id=x.category_id WHERE x.article_id=a.id LIMIT 1) category_name";try{$latest=query("SELECT a.*, $catName FROM articles a WHERE a.status='published' AND a.published_at<=NOW() ORDER BY a.published_at DESC LIMIT 9");$featured=query("SELECT a.*, $catName FROM articles a WHERE a.status='published' AND a.published_at<=NOW() AND a.is_featured=1 ORDER BY a.published_at DESC LIMIT 3");if(!$featured)$featured=array_slice($latest,0,3);$popular=query("SELECT a.*, $catName FROM articles a WHERE a.status='published' AND a.published_at<=NOW() AND a.is_popular=1 ORDER BY a.published_at DESC LIMIT 6");if(!$popular)$popular=array_slice($latest,0,6);$categories=query('SELECT * FROM categories ORDER BY id');}catch(Throwable $x){try{$categories=query('SELECT * FROM categories ORDER BY id');}catch(Throwable $y){}}render('pages/home',['title'=>'网络安全知识_数字隐私与账户安全指南_数字安全指南','description'=>'数字安全指南优先讲解钓鱼识别、双重验证、家庭网络安全与系统更新，并提供 HTTPS、账户防护与网络加密协议原理等科普内容。','keywords'=>'钓鱼识别,双重验证,家庭网络安全,系统更新,账户安全,HTTPS,网络安全,网络加密','latest'=>$latest,'featured'=>$featured,'popular'=>$popular,'categories'=>$categories]);exit;}
if($route==='search'){$term=trim((string)($_GET['q']??''));$page=max(1,(int)($_GET['page']??1));$perPage=10;$results=[];$total=0;if($term!==''){$like='%'.$term.'%';$count=db()->prepare("SELECT COUNT(DISTINCT a.id) FROM articles a LEFT JOIN article_category ac ON ac.article_id=a.id LEFT JOIN categories c ON c.id=ac.category_id WHERE a.status='published' AND a.published_at<=NOW() AND (a.title LIKE ? OR a.content_html LIKE ? OR c.name LIKE ?)");$count->execute([$like,$like,$like]);$total=(int)$count->fetchColumn();$stmt=db()->prepare("SELECT a.*,(SELECT c.name FROM article_category x JOIN categories c ON c.id=x.category_id WHERE x.article_id=a.id LIMIT 1) category_name FROM articles a WHERE a.status='published' AND a.published_at<=NOW() AND (a.title LIKE ? OR a.content_html LIKE ? OR EXISTS(SELECT 1 FROM article_category x JOIN categories c ON c.id=x.category_id WHERE x.article_id=a.id AND c.name LIKE ?)) ORDER BY a.is_popular DESC,a.published_at DESC LIMIT ? OFFSET ?");$stmt->bindValue(1,$like);$stmt->bindValue(2,$like);$stmt->bindValue(3,$like);$stmt->bindValue(4,$perPage,PDO::PARAM_INT);$stmt->bindValue(5,($page-1)*$perPage,PDO::PARAM_INT);$stmt->execute();$results=$stmt->fetchAll();}render('pages/search',['title'=>$term!==''?'搜索：'.$term:'搜索文章','description'=>'搜索数字安全指南中的网络安全、隐私和技术文章。','term'=>$term,'results'=>$results,'total'=>$total,'page'=>$page,'pages'=>(int)ceil($total/$perPage)]);exit;}
if(in_array($route,['rss.xml','sitemap-articles.xml','sitemap-categories.xml'],true)){require dirname(__DIR__).'/app/seo.php';exit;}
if($route==='tools'){$guides=[];try{$guides=query("SELECT a.*, (SELECT c.name FROM article_category x JOIN categories c ON c.id=x.category_id WHERE x.article_id=a.id LIMIT 1) category_name FROM articles a WHERE a.status='published' AND a.published_at<=NOW() AND a.slug IN ('what-is-vpn','vpn-vs-proxy','what-is-wireguard','what-is-vless','network-traffic-encryption','choose-privacy-tools','what-is-dns-leak','what-is-https') ORDER BY FIELD(a.slug,'what-is-vpn','what-is-wireguard','what-is-vless','vpn-vs-proxy','network-traffic-encryption','what-is-dns-leak','what-is-https','choose-privacy-tools')");}catch(Throwable $x){}render('pages/tools',['title'=>'网络加密与安全工具基础_协议边界说明_数字安全指南','description'=>'了解网络加密、隧道协议与安全工具的基础知识。涉及商业项目时以「广告 / 商业链接」明确标注。','keywords'=>'网络加密,隧道协议,WireGuard,HTTPS,安全工具,商业链接','guides'=>$guides]);exit;}
if(in_array($route,['about','contact','privacy-policy','terms'],true)){$staticMeta=['about'=>['title'=>'关于我们_数字安全指南编辑原则','description'=>'了解数字安全指南的定位、编辑原则与商业关系披露。','keywords'=>'关于我们,数字安全指南,编辑原则'],'contact'=>['title'=>'联系我们_选题纠错与微信联系','description'=>'通过邮件或微信公众号联系数字安全指南编辑团队，反馈纠错与选题建议。','keywords'=>'联系我们,选题建议,微信公众号'],'privacy-policy'=>['title'=>'隐私政策_数字安全指南','description'=>'说明本站日志、Cookie 与第三方链接的数据处理原则。','keywords'=>'隐私政策,数据最小化,Cookie'],'terms'=>['title'=>'使用条款_内容边界与合规声明','description'=>'本站内容仅供科普参考，请遵守中华人民共和国法律法规。','keywords'=>'使用条款,合规声明,科普声明']][$route];render('pages/static',['page'=>$route,'title'=>$staticMeta['title'],'description'=>$staticMeta['description'],'keywords'=>$staticMeta['keywords']]);exit;}
if(preg_match('#^articles/([a-z0-9-]+)$#',$route,$m)){$rows=query("SELECT a.*,GROUP_CONCAT(DISTINCT c.name SEPARATOR '、') categories,GROUP_CONCAT(DISTINCT c.slug SEPARATOR ',') category_slugs FROM articles a LEFT JOIN article_category ac ON ac.article_id=a.id LEFT JOIN categories c ON c.id=ac.category_id WHERE a.slug=? AND a.status='published' AND a.published_at<=NOW() GROUP BY a.id",[$m[1]]);if(!$rows){http_response_code(404);render('pages/404',['title'=>'页面未找到']);exit;}$art=$rows[0];$kwMap=['what-is-vpn'=>'VPN原理,隧道加密,企业远程接入,威胁模型,网络加密','vpn-vs-proxy'=>'VPN与代理区别,信任边界,企业远程接入,隧道协议,网络加密','what-is-wireguard'=>'WireGuard协议,Noise握手,Cryptokey Routing,企业VPN原理,网络加密','what-is-vless'=>'VLESS协议,Xray,TLS,UUID认证,网络加密','what-is-dns-leak'=>'DNS泄露,DoH,DoT,隧道DNS,网络加密','network-traffic-encryption'=>'网络流量加密,TLS,HTTPS,元数据,网络加密','choose-privacy-tools'=>'隐私工具选型,威胁模型,开源审计,账户安全,安全工具','identify-phishing-attacks'=>'网络钓鱼,钓鱼识别,账户安全,诈骗防范','two-factor-authentication-guide'=>'双重验证,2FA,TOTP,账户安全','what-is-https'=>'HTTPS,TLS,证书验证,传输加密','protect-online-accounts'=>'账户安全,密码管理,会话管理,防盗号'];$kw=$kwMap[$art['slug']]??implode(',',array_slice(array_values(array_filter(array_unique(array_merge(explode('、',str_replace('VPN技术','网络加密技术',(string)($art['categories']??''))),[preg_replace('/[：:].*$/u','',(string)$art['title'])])))),0,8));render('articles/show',['article'=>$art,'title'=>$art['seo_title']?:$art['title'],'description'=>$art['meta_description'],'keywords'=>$kw]);exit;}
if(preg_match('#^category/([a-z0-9-]+)$#',$route,$m)){$cats=query('SELECT * FROM categories WHERE slug=?',[$m[1]]);if(!$cats){http_response_code(404);render('pages/404',['title'=>'页面未找到']);exit;}$page=max(1,(int)($_GET['page']??1));$perPage=12;$q=db()->prepare("SELECT a.* FROM articles a JOIN article_category ac ON ac.article_id=a.id WHERE ac.category_id=? AND a.status='published' AND a.published_at<=NOW() ORDER BY a.is_featured DESC,a.published_at DESC LIMIT ? OFFSET ?");$q->bindValue(1,$cats[0]['id'],PDO::PARAM_INT);$q->bindValue(2,$perPage,PDO::PARAM_INT);$q->bindValue(3,($page-1)*$perPage,PDO::PARAM_INT);$q->execute();$articles=$q->fetchAll();$countQ=db()->prepare("SELECT COUNT(*) FROM articles a JOIN article_category ac ON ac.article_id=a.id WHERE ac.category_id=? AND a.status='published' AND a.published_at<=NOW()");$countQ->execute([$cats[0]['id']]);$pages=(int)ceil((int)$countQ->fetchColumn()/$perPage);$cat=$cats[0];$catTitle=$cat['seo_title']?:($cat['name'].'_数字安全指南');$catDesc=$cat['meta_description']?:($cat['description']??'');$catKw=$cat['name'].',网络安全,数字安全指南';render('category/index',['category'=>$cat,'articles'=>$articles,'page'=>$page,'pages'=>$pages,'title'=>$catTitle,'description'=>$catDesc,'keywords'=>$catKw]);exit;}
http_response_code(404);render('pages/404',['title'=>'页面未找到']);
